DROP TABLE IF EXISTS `mf_loan_products`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `mf_loan_products` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `name` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `min_loan_amount` decimal(14,2) DEFAULT NULL,
  `max_loan_amount` decimal(14,2) DEFAULT NULL,
  `document_charge_percentage` decimal(8,4) DEFAULT NULL,
  `base_document_charge_allowed_months` int unsigned DEFAULT NULL,
  `additional_document_charge_per_extra_month_percentage` decimal(8,4) DEFAULT NULL,
  `stamp_charge_percentage` decimal(8,4) DEFAULT NULL,
  `insurance_charge_percentage` decimal(8,4) DEFAULT NULL,
  `interest_rate` decimal(12,7) NOT NULL DEFAULT '0.0000000',
  `interest_type` enum('flat','reducing') CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'flat',
  `interest_calculation_scheme` enum('day','week','month','year') COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'month',
  `terms_count` int unsigned NOT NULL DEFAULT '1',
  `refund_option` enum('day','week','month') CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'month',
  `assumed_month_days` tinyint unsigned NOT NULL DEFAULT '30',
  `is_active` tinyint(1) NOT NULL DEFAULT '1',
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `mf_loan_products_name_unique` (`name`)
) ENGINE=InnoDB AUTO_INCREMENT=6 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
